      "path": "index.js",
      "content": "/**
 * ikun-theme-skin — node half.
 * The empty apply exists so the row activates in the host loader; the browser
 * half ships the theme skin through exports["./client"].
 */
export function apply() {}
"
    },
    {
      "path": "client.js",
      "content": "/**
 * ikun-theme-skin — browser half (client plugin bundle).
 *
 * 由 scripts/build-bundle.mjs 从 src/client.js 生成，请勿手改本文件；
 * 修改请编辑 src/client.js 后重新运行 node scripts/build-bundle.mjs。
 * Loaded through the package's dsh.client declaration (see package.json),
 * using the vendored module loader — the same shape as cyber-particle and the
 * shipped ui-* packages. The factory returns the cordis plugin object; the
 * window guard keeps node-side (host boot) evaluation safe.
 */
if (typeof window !== 'undefined' && typeof window.__ModuleLoader__ !== 'undefined') {
  window.__ModuleLoader__.load({
    id: 'ikun-theme-skin',
    factory(require) {
      const React = require('react')

      /** Inject a stylesheet and return a disposer (replaces the dynamic runner's styles builtin). */
      function insertStyle(css) {
        const el = document.createElement('style')
        el.type = 'text/css'
        el.textContent = css
        document.head.appendChild(el)
        return () => { if (el.parentNode) el.parentNode.removeChild(el) }
      }

      return {
        inject: ['slots', 'theme', 'timer'],
        apply(ctx) {
          const theme = ctx.get('theme')
          const slots = ctx.get('slots')
          const timer = ctx.get('timer')
          if (!theme || !slots) return

          // ---------- 音频与参数 ----------
