          '.ikun-theme-tag{display:inline-block;margin-top:8px;padding:2px 8px;border-radius:999px;background:var(--dsw-alias-brand-primary,#2f7fe0);color:#fff;font-size:11px;font-weight:700}',
          '.ikun-wall-row,.ikun-music-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px;border-radius:12px;background:var(--dsw-alias-bg-layer-1,#fff);border:1px solid var(--dsw-alias-border-l1,#dde3f2)}',
